cat > src/lib/billing-lock.ts <<'EOF'
/**
 * The read-only lock a workspace falls under while its subscription is not in
 * good standing. `lockReasonFor()` is the single statement of the rule; the
 * billing service evaluates it against the stored subscription before every
 * member write.
 */
import type { Subscription, WorkspaceLockReason } from "@/types/billing";
import type { OrgId } from "@/types/common";

/** Raised when a member write is attempted against a locked workspace. */
export class WorkspaceLockedError extends Error {
  readonly code = "plan_limit_exceeded" as const;

  constructor(
    readonly orgId: OrgId,
    readonly reason: WorkspaceLockReason,
  ) {
    super(`Workspace ${orgId} is read-only: ${describeReason(reason)}`);
    this.name = "WorkspaceLockedError";
  }
}

function describeReason(reason: WorkspaceLockReason): string {
  switch (reason) {
    case "past_due":
      return "its subscription is past due";
    case "canceled":
      return "its subscription has been canceled";
    case "trial_ended":
      return "its trial has ended";
  }
}

/** True once `now` is at or after `at`. An unreadable date never matches. */
function reached(at: string, now: Date): boolean {
  return now.getTime() >= new Date(at).getTime();
}

/**
 * Why the workspace is locked at `now`, or `null` when it is writable.
 *
 * No subscription row and `active` are writable; `past_due` is locked; a
 * trial locks once its period end is reached; a cancellation locks once its
 * date is reached (a missing date means "canceled now").
 */
export function lockReasonFor(
  subscription: Subscription | null,
  now: Date = new Date(),
): WorkspaceLockReason | null {
  if (subscription === null) return null;

  switch (subscription.status) {
    case "active":
      return null;
    case "past_due":
      return "past_due";
    case "trialing":
      return reached(subscription.currentPeriodEnd, now) ? "trial_ended" : null;
    case "canceled":
      return subscription.cancelAt === null ||
        reached(subscription.cancelAt, now)
        ? "canceled"
        : null;
    default:
      return null;
  }
}
