      return "its subscription has been canceled";
    case "trial_ended":
      return "its trial has ended";
  }
}

/** True once `now` is at or after `at`. An unreadable date never matches. */
function reached(at: string, now: Date): boolean {
  return now.getTime() >= new Date(at).getTime();
}

/**
 * Why the workspace is locked at `now`, or `null` when it is writable.
 *
 * No subscription row and `active` are writable; `past_due` is locked; a
 * trial locks once its period end is reached; a cancellation locks once its
 * date is reached (a missing date means "canceled now").
 */
export function lockReasonFor(
  subscription: Subscription | null,
  now: Date = new Date(),
): WorkspaceLockReason | null {
  if (subscription === null) return null;

  switch (subscription.status) {
    case "active":
      return null;
    case "past_due":
      return "past_due";
    case "trialing":
      return reached(subscription.currentPeriodEnd, now) ? "trial_ended" : null;
    case "canceled":
      return subscription.cancelAt === null ||
        reached(subscription.cancelAt, now)
        ? "canceled"
        : null;
    default:
      return null;
  }
}
